package localchat;
import java.nio.file.*;
import java.util.*;
import javax.swing.*;

/** Verify actual request payloads, not model compliance: clean Normal epochs and intact archives. */
public final class NormalModeTest {
    static int checks;
    static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    static void mode(LocalChat a,boolean tools)throws Exception{var menu=(JPopupMenu)FeatureTest.call(a,"buildModeMenu",new Class<?>[]{});((JMenuItem)menu.getComponent(tools?0:1)).doClick();}
    static List<ChatClient.Message> history(LocalChat a)throws Exception{return FeatureTest.field(a,"history");}
    static JTextField system(LocalChat a)throws Exception{return FeatureTest.field(a,"systemField");}
    static void ask(LocalChat a,String text)throws Exception{FeatureTest.edt(()->{AttachmentTest.input(a).setText(text);FeatureTest.call(a,"send",new Class<?>[]{});});FeatureTest.idle(a);}
    static String wire(Object request){return Json.write(request);}
    static void state(){
        var state=new Conversations.State();check(!state.enterMode(true,0),"fresh MBS keeps initial history");
        List<ChatClient.Message> raw=new ArrayList<>();for(int i=0;i<4;i++){raw.add(ChatClient.Message.user("MBS-old-question"));raw.add(ChatClient.Message.assistant("MBS-old-answer",List.of(),"model"));}
        state.memory.summary="MBS-summary";state.memory.through=4;state.contextAnchorInput=100;state.contextAnchorSignature="old";state.bookmarks.add(0);
        check(state.enterMode(false,raw.size()),"MBS to Normal changes context epoch");check(state.memory.start==8&&state.memory.through==8&&state.memory.view(raw).isEmpty(),"entire old MBS history and compact summary excluded");check(state.contextAnchorInput==-1&&state.contextAnchorSignature.isEmpty()&&state.bookmarks.contains(0),"old API anchor invalidated, bookmarks preserved");
        for(int i=0;i<4;i++){raw.add(ChatClient.Message.user("Normal-question-"+i));raw.add(ChatClient.Message.assistant("Normal-answer-"+i,List.of(),"model"));}
        check(state.memory.boundary(raw)==12,"compaction boundary uses raw archive offsets in current epoch");state.memory.summary="Normal summary";state.memory.through=12;state.memory.question="retained exact question";
        var active=state.memory.view(raw);check(active.size()==6&&active.get(0).content.contains("Normal summary")&&active.get(2).content.equals("Normal-question-2"),"new Normal compaction retains summary, question and latest exchanges");
        var restored=Conversations.State.fromJson(state.toJson(),raw.size());check(restored.contextMode.equals("normal")&&restored.memory.start==8&&restored.memory.view(raw).size()==6,"context epoch and summary persist on reopen");
        check(!restored.enterMode(false,raw.size())&&restored.memory.start==8,"resuming same mode does not reset its valid history");check(restored.enterMode(true,raw.size())&&restored.memory.view(raw).isEmpty(),"switch back MBS excludes Normal context");check(raw.size()==16&&raw.get(0).content.equals("MBS-old-question"),"mode changes never edit archive");
        var legacy=Conversations.State.fromJson(Json.obj("toolsEnabled",false,"summary","MBS old summary","compactedThrough",4),8);check(legacy.enterMode(false,8)&&legacy.memory.view(raw.subList(0,8)).isEmpty(),"legacy Normal contaminated context safely migrated");
        var bad=Conversations.State.fromJson(Json.obj("contextMode","normal","activeContextStart",999,"summary","stale","compactedThrough",2),8);check(bad.memory.start==8&&bad.memory.summary.isEmpty(),"out-of-range epoch clamped and stale summary rejected");
    }
    static void payloads(Path home)throws Exception{
        try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("General answer",30,5)),FeatureTest.json(FeatureTest.answer("Second general answer",45,6)),FeatureTest.json(FeatureTest.answer("MBS answer",50,7)),FeatureTest.json(FeatureTest.answer("Clean again",20,4)),FeatureTest.json(FeatureTest.answer("Still clean",25,4)))){
            LocalChat[] a={null};Path[] saved={null};String[] original={null};
            FeatureTest.edt(()->{
                a[0]=AttachmentTest.window(home,server.url());Properties config=FeatureTest.field(a[0],"config");config.setProperty("memory.enabled","true");config.setProperty("memory.allowTools","true");
                var store=(LocalMemories)FeatureTest.call(a[0],"memories",new Class<?>[]{});store.add("","GLOBAL-MBS-PERSONA control PDFs","manual","");store.add("123456","PROJECT-MEMORY-SECRET fixture","manual","");store.add("","Toate conversatiile se poarta in limba romana.","manual","");
                Files.writeString(home.resolve("reguli.md"),"MANUAL-MBS-RULE run PDFCONTROL");system(a[0]).setText("CUSTOM-MBS-SYSTEM");history(a[0]).add(ChatClient.Message.user("Continua proiectul 123456"));history(a[0]).add(ChatClient.Message.assistant("ARCHIVED-MBS-CLAIM PDFCONTROL",List.of(new ChatClient.ToolCall("t","read_file",Json.obj("path","drawing.pdf"))),"fixture"));history(a[0]).add(ChatClient.Message.toolResult("t","MBS-TOOL-RESULT",false));history(a[0]).add(ChatClient.Message.assistant("Done",List.of(),"fixture"));
                var state=AttachmentTest.state(a[0]);state.memory.summary="COMPACT-MBS-SUMMARY";state.memory.through=4;state.bookmarks.add(0);state.contextAnchorInput=70000;state.contextAnchorCount=4;state.contextAnchorThrough=4;
                original[0]=Json.write(history(a[0]).stream().map(ChatClient.Message::toJson).toList());AttachmentTest.input(a[0]).setText("draft preserved");mode(a[0],false);
                check(system(a[0]).getText().isEmpty()&&AttachmentTest.input(a[0]).getText().equals("draft preserved"),"Normal starts with blank own system prompt and preserves draft");check(AttachmentTest.state(a[0]).memory.start==4&&AttachmentTest.state(a[0]).contextAnchorInput==-1,"mode selector resets compact memory and API anchors immediately");
                FeatureTest.call(a[0],"compactMemory",new Class<?>[]{});check(server.requests.isEmpty(),"old MBS archive cannot trigger manual compaction or inference in Normal");((JComboBox<?>)FeatureTest.field(a[0],"responseLanguageBox")).setSelectedIndex(0);system(a[0]).setText("NORMAL-CUSTOM-INSTRUCTION concise examples");
            });
            ask(a[0],"Ce stii sa faci?");
            FeatureTest.edt(()->{
                String request=wire(server.requests.get(0));check(Json.get(server.requests.get(0),"tools")==null,"Normal wire has no tool definitions");for(String excluded:List.of("CUSTOM-MBS-SYSTEM","GLOBAL-MBS-PERSONA","PROJECT-MEMORY-SECRET","MANUAL-MBS-RULE","ARCHIVED-MBS-CLAIM","MBS-TOOL-RESULT","COMPACT-MBS-SUMMARY","PDFCONTROL","Toate conversatiile","read_skill",home.toString()))check(!request.contains(excluded),"Normal excludes "+excluded);
                check(request.contains("NORMAL-CUSTOM-INSTRUCTION")&&Json.str(server.requests.get(0),"messages",1,"content").equals("Ce stii sa faci?"),"explicit Normal system and exact new question retained");check(AttachmentTest.state(a[0]).usage.requests==1&&history(a[0]).size()==6,"only actual new inference counted, archive retained");check(Json.write(history(a[0]).subList(0,4).stream().map(ChatClient.Message::toJson).toList()).equals(original[0]),"all original MBS messages untouched");
                FeatureTest.call(a[0],"saveConversation",new Class<?>[]{});saved[0]=FeatureTest.field(a[0],"conversationFile");FeatureTest.command(a[0],"/new separate");FeatureTest.call(a[0],"openSession",new Class<?>[]{Conversations.Saved.class},Conversations.load(saved[0]));check(server.requests.size()==1&&AttachmentTest.state(a[0]).memory.start==4,"reopening clean Normal preserves its context without API calls");
            });
            ask(a[0],"Explain further");
            FeatureTest.edt(()->{String request=wire(server.requests.get(1));check(request.contains("General answer")&&!request.contains("ARCHIVED-MBS-CLAIM"),"Normal keeps its own previous answer after reopen");mode(a[0],true);check(system(a[0]).getText().equals("CUSTOM-MBS-SYSTEM"),"MBS system restored separately");});
            ask(a[0],"Continua proiectul 123456");
            FeatureTest.edt(()->{String request=wire(server.requests.get(2));check(Json.get(server.requests.get(2),"tools") instanceof List<?> tools&&!tools.isEmpty(),"MBS restores actual tool definitions");check(request.contains("GLOBAL-MBS-PERSONA")&&request.contains("PROJECT-MEMORY-SECRET")&&request.contains("MANUAL-MBS-RULE")&&request.contains("CUSTOM-MBS-SYSTEM"),"MBS retains rules, global and correct project memories");check(!request.contains("Second general answer")&&!request.contains("NORMAL-CUSTOM-INSTRUCTION"),"Normal context and custom prompt do not leak back into MBS");((JCheckBox)FeatureTest.field(a[0],"toolsBox")).doClick();check(system(a[0]).getText().equals("NORMAL-CUSTOM-INSTRUCTION concise examples"),"top tools checkbox uses same mode isolation and restores Normal prompt");});
            ask(a[0],"Retine pentru proiectul 654321: prefer rapoarte PDF");
            FeatureTest.edt(()->{var store=(LocalMemories)FeatureTest.call(a[0],"memories",new Class<?>[]{});check(store.all().size()==3,"Normal creates no implicit or explicit persistent memories");check(!wire(server.requests.get(3)).contains("MBS answer"),"second Normal epoch excludes MBS final answer");Files.writeString(store.file,"deliberately invalid memory fixture");((JComboBox<?>)FeatureTest.field(a[0],"responseLanguageBox")).setSelectedIndex(1);});
            ask(a[0],"Ce stii sa faci?");
            FeatureTest.edt(()->{check(wire(server.requests.get(4)).contains("Dutch (Nederlands)"),"fixed language still controls Normal independent of memory");check(server.requests.size()==5,"unreadable persistent memory cannot block Normal or create extra inference");FeatureTest.call(a[0],"saveConversation",new Class<?>[]{});var state=Conversations.load(saved[0]).state();check(state.bookmarks.contains(0)&&state.contextMode.equals("normal"),"bookmarks and active mode survive save");a[0].dispose();a[0]=AttachmentTest.window(home,server.url());FeatureTest.call(a[0],"openSession",new Class<?>[]{Conversations.Saved.class},Conversations.load(saved[0]));check(AttachmentTest.state(a[0]).memory.start==10&&server.requests.size()==5,"application restart keeps second epoch and never infers");a[0].dispose();});
        }
    }
    static void compactedEpoch(Path home,boolean automatic)throws Exception{
        try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("NORMAL-ONLY-FACTUAL-SUMMARY",100,15)),FeatureTest.json(FeatureTest.answer("Final normal answer",120,10)))){
            LocalChat[] a={null};FeatureTest.edt(()->{a[0]=AttachmentTest.window(home,server.url());history(a[0]).add(ChatClient.Message.user("OLD-MBS-ONLY"));history(a[0]).add(ChatClient.Message.assistant("OLD-MBS-REPLY",List.of(),"fixture"));mode(a[0],false);
                int count=automatic?1:4;for(int i=0;i<count;i++){history(a[0]).add(ChatClient.Message.user("Normal evidence "+"fact ".repeat(automatic?500:1200)));history(a[0]).add(ChatClient.Message.assistant("Verified normal result",List.of(),"fixture"));}
                ((WorkspacePanel)FeatureTest.field(a[0],"workspace")).limit.setValue(automatic?8192:32768);AttachmentTest.state(a[0]).autoCompact=automatic;AttachmentTest.state(a[0]).autoThreshold=95;
                if(automatic){var state=AttachmentTest.state(a[0]);state.contextAnchorInput=7500;state.contextAnchorCount=history(a[0]).size();state.contextAnchorThrough=state.memory.through;state.contextAnchorProfile=(String)FeatureTest.call(a[0],"contextProfile",new Class<?>[]{});state.contextAnchorSignature=ContextGuard.signature((String)FeatureTest.call(a[0],"plainPrompt",new Class<?>[]{}),List.of());}
                if(!automatic)FeatureTest.call(a[0],"compactMemory",new Class<?>[]{});
            });if(!automatic)FeatureTest.idle(a[0]);ask(a[0],"Continue this general discussion");
            FeatureTest.edt(()->{check(server.requests.size()==2,"only summary and final inference in compacted Normal epoch");for(Object request:server.requests){check(!wire(request).contains("OLD-MBS"),"compaction input and final request exclude prior mode entirely");check(!wire(request).contains("Hoofdregel")&&!wire(request).contains("Preserve exact user project IDs"),"Normal compaction has a general conversation policy");}check(wire(server.requests.get(1)).contains("NORMAL-ONLY-FACTUAL-SUMMARY"),"final inference uses new Normal summary");var state=AttachmentTest.state(a[0]);check(state.memory.start==2&&state.memory.through==(automatic?5:6),"compaction maps active offsets back to complete archive with nonzero epoch");check(state.contextAnchorCount==history(a[0]).size()-1&&state.contextAnchorThrough==state.memory.through,"API token anchor uses complete archive offsets");FeatureTest.call(a[0],"saveConversation",new Class<?>[]{});Path file=FeatureTest.field(a[0],"conversationFile");var saved=Conversations.load(file);check(saved.state().memory.start==2&&saved.messages().get(0).content.equals("OLD-MBS-ONLY"),"compacted context and untouched older archive persist together");mode(a[0],true);check(AttachmentTest.state(a[0]).memory.summary.isBlank()&&AttachmentTest.state(a[0]).contextAnchorInput==-1,"mode switch discards only active Normal summary and calibrated anchor");a[0].dispose();});
        }
    }
    static void legacyAndDefaults(Path home)throws Exception{
        try(var server=new FeatureTest.Server()){FeatureTest.edt(()->{
            LocalChat a=AttachmentTest.window(home,server.url());var legacy=new Conversations.State();legacy.toolsEnabled=false;legacy.systemPrompt="OLD-MBS-CUSTOM";legacy.memory.summary="OLD-MBS-SUMMARY";legacy.memory.through=2;legacy.bookmarks.add(0);legacy.draft="unsent legacy message";
            Path file=Conversations.newFile(home.resolve("conversatii"));Conversations.save(file,home.toString(),List.of(ChatClient.Message.user("OLD-MBS-QUESTION"),ChatClient.Message.assistant("OLD-MBS-ANSWER",List.of(),"fixture")),legacy);
            FeatureTest.call(a,"openSession",new Class<?>[]{Conversations.Saved.class},Conversations.load(file));check(system(a).getText().isBlank()&&AttachmentTest.state(a).memory.view(history(a)).isEmpty(),"legacy Normal load clears inherited system, summary and active history");check(AttachmentTest.input(a).getText().equals("unsent legacy message")&&AttachmentTest.state(a).bookmarks.contains(0),"legacy migration keeps unsent draft and bookmarks");
            FeatureTest.call(a,"saveConversation",new Class<?>[]{});var migrated=Conversations.load(file);check(migrated.messages().size()==2&&migrated.state().contextMode.equals("normal")&&migrated.state().memory.start==2,"legacy migration persists once, without losing original answers");
            system(a).setText("NORMAL-SAVED-DEFAULT");FeatureTest.call(a,"saveDefaults",new Class<?>[]{});FeatureTest.command(a,"/new fresh Normal");check(system(a).getText().equals("NORMAL-SAVED-DEFAULT"),"explicit Normal default applies only to new Normal chat");
            mode(a,true);system(a).setText("MBS-SAVED-DEFAULT");FeatureTest.call(a,"saveDefaults",new Class<?>[]{});FeatureTest.command(a,"/new fresh MBS");check(system(a).getText().equals("MBS-SAVED-DEFAULT"),"MBS default remains separate from Normal default");mode(a,false);check(system(a).getText().equals("NORMAL-SAVED-DEFAULT"),"new MBS chat can select own saved clean Normal prompt");check(server.requests.isEmpty(),"migration, defaults and mode switches never infer");a.dispose();
        });}
    }
    static void languages(Path home)throws Exception{
        try(var server=new FeatureTest.Server()){FeatureTest.edt(()->{LocalChat a=AttachmentTest.window(home,server.url());for(int i=0;i<6;i++)for(int theme=0;theme<2;theme++){((JComboBox<?>)FeatureTest.field(a,"languageBox")).setSelectedIndex(i);((JComboBox<?>)FeatureTest.field(a,"themeBox")).setSelectedIndex(theme);mode(a,false);JButton button=FeatureTest.field(a,"bottomMode");check(button.getText().equals(I18n.text("Normal"))&&button.getToolTipText().equals(I18n.text("Normal: fara unelte, reguli MBS sau memorii salvate. Schimbarea modului incepe un context nou.")),"mode semantics translated in six languages and both themes");check(I18n.contains("Mod schimbat: context nou; istoricul ramane vizibil.")&&I18n.contains("Automat (in functie de mod)"),"new labels translated");mode(a,true);}check(server.requests.isEmpty(),"language, theme and profile selection are local");a.dispose();});}
    }
    public static void main(String[] args)throws Exception{Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");System.out.println("QA home: "+home);try{state();payloads(home.resolve("payloads"));compactedEpoch(home.resolve("manual-epoch"),false);compactedEpoch(home.resolve("auto-epoch"),true);legacyAndDefaults(home.resolve("legacy"));languages(home.resolve("languages"));System.out.println("PASS: "+checks+" clean Normal mode checks; wire payloads, mode transitions, compaction boundaries, restart and six languages/themes");}finally{FeatureTest.edt(()->{for(var w:java.awt.Window.getWindows())w.dispose();});}System.exit(0);}
}
